/**
 * Represents a welcome message data transfer object.
 */
public class WelcomeDTO {
    private final String message;
    /**
     * Constructs a new WelcomeDTO with the specified message.
     * @param message the welcome message
     */
    public WelcomeDTO(String message) {
        this.message = message;
    }
    /**
     * Returns the welcome message.
     * @return the welcome message
     */
    public String getMessage() {
        return message;
    }
}

private void assertWelcomeMessage(String name, String expectedMessage) throws Exception {
    mockMvc.perform(get("/api/welcome").param("name", name))
            .andExpect(status().isOk())
            .andExpect(content().contentType("application/json"))
            .andExpect(jsonPath("$.message").value(expectedMessage));
}

public void welcomeEndpointReturnsDefaultMessage_WhenNoNameProvided() throws Exception {
    assertWelcomeMessage(null, "Hola, bienvenido ..., esto es un demo");
}

public void welcomeEndpointReturnsCustomMessage_WhenNameProvided() throws Exception {
    assertWelcomeMessage("Juan", "Hola, bienvenido Juan, esto es un demo");
}

